import { useState, useEffect } from 'react';

function UserProfile({ userId }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Must be declared inside to access latest userId
    const controller = new AbortController();

    async function fetchUser() {
      try {
        setLoading(true);
        const res = await fetch(`/api/users/${userId}`, {
          signal: controller.signal
        });
        if (!res.ok) throw new Error('Failed to fetch');
        const data = await res.json();
        setUser(data);
      } catch (err) {
        if (err.name !== 'AbortError') setError(err.message);
      } finally {
        setLoading(false);
      }
    }

    fetchUser();

    // Cleanup: abort request if userId changes or component unmounts
    return () => controller.abort();
  }, [userId]); // Dependency: re-run when userId changes

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error}</p>;
  return <div>{user?.name}</div>;
}

import { useRef, useEffect } from 'react';

// Use Case 1: Access DOM elements directly
function SearchInput() {
  const inputRef = useRef(null);

  useEffect(() => {
    inputRef.current.focus(); // focus on mount
  }, []);

  return <input ref={inputRef} placeholder="Search..." />;
}

// Use Case 2: Persist values across renders WITHOUT triggering re-render
function Timer() {
  const [time, setTime] = useState(0);
  const intervalRef = useRef(null); // store interval ID

  const start = () => {
    intervalRef.current = setInterval(() => setTime(t => t + 1), 1000);
  };
  const stop = () => clearInterval(intervalRef.current);

  useEffect(() => () => clearInterval(intervalRef.current), []);

  return (
    <div>
      <p>{time}s</p>
      <button onClick={start}>Start</button>
      <button onClick={stop}>Stop</button>
    </div>
  );
}

import { useMemo, useCallback, useState } from 'react';

function ProductList({ products, onAddToCart }) {
  const [filter, setFilter] = useState('');
  const [sortAsc, setSortAsc] = useState(true);

  // useMemo: cache expensive computation between renders
  const filteredProducts = useMemo(() => {
    console.log('Filtering...');
    return products
      .filter(p => p.name.toLowerCase().includes(filter))
      .sort((a, b) => sortAsc
        ? a.name.localeCompare(b.name)
        : b.name.localeCompare(a.name)
      );
  }, [products, filter, sortAsc]); // only recomputes when these change

  // useCallback: stable function reference for child components
  const handleAdd = useCallback((product) => {
    onAddToCart(product);
    // ... other logic
  }, [onAddToCart]); // stable unless onAddToCart changes

  return (
    <>
      <input value={filter} onChange={e => setFilter(e.target.value)} />
      {filteredProducts.map(p => (
        <ProductCard key={p.id} product={p} onAdd={handleAdd} />
      ))}
    </>
  );
}

// useFetch — reusable data fetching hook
function useFetch(url) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();
    fetch(url, { signal: controller.signal })
      .then(r => r.json())
      .then(setData)
      .catch(e => { if (e.name !== 'AbortError') setError(e.message); })
      .finally(() => setLoading(false));
    return () => controller.abort();
  }, [url]);

  return { data, loading, error };
}

// useLocalStorage — syncs state to localStorage
function useLocalStorage(key, initialValue) {
  const [value, setValue] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem(key)) ?? initialValue;
    } catch { return initialValue; }
  });

  const setLocalValue = (newValue) => {
    setValue(newValue);
    localStorage.setItem(key, JSON.stringify(newValue));
  };

  return [value, setLocalValue];
}

// Usage — clean component code
function App() {
  const { data: users, loading } = useFetch('/api/users');
  const [theme, setTheme] = useLocalStorage('theme', 'dark');

  if (loading) return <Spinner />;
  return <UserList users={users} theme={theme} />;
}

import { useReducer } from 'react';

// State shape and initial value
const initialState = { count: 0, step: 1, history: [] };

// Reducer: pure function (state, action) => newState
function reducer(state, action) {
  switch (action.type) {
    case 'INCREMENT':
      return {
        ...state,
        count: state.count + state.step,
        history: [...state.history, state.count]
      };
    case 'DECREMENT':
      return { ...state, count: state.count - state.step };
    case 'SET_STEP':
      return { ...state, step: action.payload };
    case 'RESET':
      return initialState;
    default:
      return state;
  }
}

function Counter() {
  const [state, dispatch] = useReducer(reducer, initialState);

  return (
    <div>
      <p>Count: {state.count} (step: {state.step})</p>
      <button onClick={() => dispatch({ type: 'INCREMENT' })}>+</button>
      <button onClick={() => dispatch({ type: 'DECREMENT' })}>-</button>
      <input
        type="number"
        onChange={e => dispatch({ type: 'SET_STEP', payload: +e.target.value })}
      />
    </div>
  );
}
